import{_ as e,c as p,o as r,ah as s}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"15、【谦】 艮下坤上","description":"周易尚氏学 - 15、【谦】 艮下坤上","frontmatter":{"title":"15、【谦】 艮下坤上","description":"周易尚氏学 - 15、【谦】 艮下坤上"},"headers":[],"relativePath":"zh/classics/shangshi/020.md","filePath":"zh/classics/shangshi/020.md"}'),i={name:"zh/classics/shangshi/020.md"};function t(h,a,n,l,c,o){return r(),p("div",null,[...a[0]||(a[0]=[s('<h1 id="_15、【谦】-艮下坤上" tabindex="-1">15、【谦】 艮下坤上 <a class="header-anchor" href="#_15、【谦】-艮下坤上" aria-label="Permalink to “15、【谦】 艮下坤上”">​</a></h1><p>山本高而在地下。故曰谦。谦不自足也。三承乘皆阴。故曰亨。艮为君子。坤为终。故曰君子有终。谦嗛同。汉书艺文志易之嗛嗛。尹翁归传。温良嗛退。注皆云同谦。嗛不足也。少也。故彖传以盈为对文。</p><p>彖曰。谦亨。天道下济而光明。地道卑而上行。天道亏盈而益谦。地道变盈而流谦。鬼神害盈而福谦。人道恶盈而好谦。谦尊而光。卑而不可踰。君子之终也。</p><p>艮为天。为光明。(象本易林。实易以艮为天为光明之处甚多。详焦氏易诂。荀爽谓阳来成坎。日月之象。故光明。非。)居下卦。故曰下济。济止也。言一阳止于三而成艮也。艮止也。坤为卑。居上卦。故曰卑而上行。互震为行也。天道亏盈四句。申有终之原理。变毁也。坤为亏。为毁。为害。为恶。为鬼。震为神。(象失传。详焦氏易诂)为人。艮一阳在上。故尊。(艮为官。为君子。人知之。乃为尊又不知。只易林以艮为贵为尊。)而光。卑谓居下卦。虞翻谓三位贱。故卑。非也。卑而不可踰者。艮为山。艮止坎险。故虽卑退。而不能踰越。终获福也。</p><p>象曰。地中有山。谦。君子以捊多益寡。称物平施。</p><p>捊王弼本作裒。释文云。郑荀董蜀才皆作捋。取也。捊裒音同通用。阳来内故曰益。艮手故曰取。说卦坤为众。故为多。剥下五阴。互三坤。多极矣。今上来益三。居中以界上下。坤为物。下物虽寡。阳来益之。上下物等。故曰称物。坎为平。物称故施平。(虞因艮多节谓艮为多。非。多白眼。多心。多眚。多字若可取象。则巽坎皆可为多。不只艮也。)</p><p>初六。谦谦君子。用涉大川。吉。</p><p>初临坎水。坎险坎陷。本不易涉。然初居下卦之下。谦而又谦。卑以自牧。故可用以涉此大川。而无不吉也。### 象曰。谦谦君子。卑以自牧也。 扬子方言。牧司也。治也。</p><p>六二。鸣谦。贞吉。</p><p>玉篇。鸣声相命也。震为鸣。二承之。三阳为二友。损。一人行则得其友。是也。诗小雅。嘤其鸣矣。求其友声。言二得承三。遂其所愿。故得意而呜也。二当位。故贞吉。</p><h3 id="象曰。鸣谦贞吉。中心得也。" tabindex="-1">象曰。鸣谦贞吉。中心得也。 <a class="header-anchor" href="#象曰。鸣谦贞吉。中心得也。" aria-label="Permalink to “象曰。鸣谦贞吉。中心得也。”">​</a></h3><p>中心得。申鸣谦之故也。卦体坎。坎为中为心。</p><p>九三。劳谦。君子有终。吉。</p><p>坎为劳卦。故曰劳谦。艮为君子。艮成终。故曰君子有终。</p><h3 id="象曰。劳谦君子。万民服也。" tabindex="-1">象曰。劳谦君子。万民服也。 <a class="header-anchor" href="#象曰。劳谦君子。万民服也。" aria-label="Permalink to “象曰。劳谦君子。万民服也。”">​</a></h3><p>三临群阴。坤众故曰万民服。</p><p>六四。无不利。撝谦。</p><p>释文撝麾同。指撝也。</p><h3 id="象曰。无不利撝谦。不违则也。" tabindex="-1">象曰。无不利撝谦。不违则也。 <a class="header-anchor" href="#象曰。无不利撝谦。不违则也。" aria-label="Permalink to “象曰。无不利撝谦。不违则也。”">​</a></h3><p>则谓三。言四顺三。而发撝其谦德也。阴顺阳。故无不利。子夏传撝谦化谦也。盖化于三而不违之也。则纯指三言。各家泛论之。非也。</p><p>六五。不当。句以其邻。利用侵伐。无不利。</p><p>坤虚故不当。震为邻。为侵伐。以。与也。言五与四顺三以征不服。无不利也。震为威武。故为侵伐为征。李鼎柞谓六五离爻。离为戈兵。故为侵伐。毛奇龄惠栋用之。非也。</p><h3 id="象曰。利用侵伐。征不服也。" tabindex="-1">象曰。利用侵伐。征不服也。 <a class="header-anchor" href="#象曰。利用侵伐。征不服也。" aria-label="Permalink to “象曰。利用侵伐。征不服也。”">​</a></h3><p>上六反君道。故曰不服。荀爽谓指五似非。</p><p>上六。鸣谦。利用行师。征邑国。</p><p>俞樾云。六二鸣谦。传曰中心得。此曰志未得。何相反若是。疑鸣当作冥。与豫升上六同例。按俞说是也。豫上六冥豫。释文云郑读为呜。鸣冥古盖同声相假。犹捊之作裒也。坤为师为邑国。震为征为行。人众势强故利。然以冥谦行之。昧于事情。故难得志。宋襄公是也。</p><h3 id="象曰。呜谦。志未得也。可用行师。征邑国也。" tabindex="-1">象曰。呜谦。志未得也。可用行师。征邑国也。 <a class="header-anchor" href="#象曰。呜谦。志未得也。可用行师。征邑国也。" aria-label="Permalink to “象曰。呜谦。志未得也。可用行师。征邑国也。”">​</a></h3><p>上应在三。三坎为志。志未得。言上为四五所阻。应三难也。</p>',28)])])}const m=e(i,[["render",t]]);export{_ as __pageData,m as default};
